<?php
require_once 'includes/db.php';require_once 'includes/functions.php';require_login();if(($_SESSION['user']['role']??'')!=='student'){header('Location: index.php');exit;}$sid=(int)($_SESSION['user']['student_id']??0);$stmt=$conn->prepare('SELECT s.*,c.course_code,c.course_title FROM student s LEFT JOIN course c ON c.course_id=s.course_id WHERE s.student_id=?');$stmt->bind_param('i',$sid);$stmt->execute();$s=$stmt->get_result()->fetch_assoc();$pageTitle='My student record';require 'includes/header.php'; ?><div class="page-heading"><div><h1>My student record</h1><p class="subheading">Your personal academic details.</p></div></div><div class="card"><?php if(!$s): ?><p>No student record is linked to your login. Please contact the university administrator.</p><?php else: ?><div class="form-grid"><?php foreach(['reg_no'=>'Registration number','first_name'=>'First name','last_name'=>'Last name','gender'=>'Gender','date_of_birth'=>'Date of birth','email'=>'Email','address'=>'Address','course_code'=>'Course code','course_title'=>'Course'] as $key=>$label): ?><div class="field"><label><?= e($label) ?></label><div><?= e($s[$key]??'—') ?></div></div><?php endforeach; ?></div><?php endif; ?></div><?php require 'includes/footer.php'; ?>